const res = yield* Operation.invoke(
  yield* Database.resolve('dxn:org.dxos.operation.discovery.queryTypes'),
  { typenames: ['com.example.type.task'] }
);
yield* print(res);

const Task = yield* Database.resolve('dxn:com.example.type.task:0.1.0');
const all = yield* Database.query(Filter.type(Task)).run;
const docsTasks = all.filter(t => /docs/i.test(t.title ?? ''));
yield* print('total tasks', all.length, 'docs-matching', docsTasks.length);
for (const t of docsTasks) {
  yield* print('-', t.title, '| was:', t.status);
  if (t.status !== 'done') Obj.update(t, (x) => { x.status = 'done'; });
}
yield* Database.flush();
const after = yield* Database.query(Filter.type(Task)).run;
yield* print('done total', after.filter(t => t.status === 'done').length);
